from datetime import datetime
import gzip
from hashlib import sha256
from io import BytesIO
import json
from pathlib import Path
import re
import signal

from numba import njit
import numpy as np
import pandas as pd
import yaml


ROOT = Path(__file__).resolve().parent
FIELDS = ("Open", "Close", "Dividends", "Capital Gains", "Stock Splits")
ANNUAL_SESSIONS = 252
PRICE_ADJUSTMENT = (
    "yfinance auto_adjust=False, split-adjusted OHLC, "
    "ex-date distributions reinvested at the actual open"
)


def rate(cost_bps, slippage_bps):
    result = (cost_bps + slippage_bps) / 10_000
    if min(cost_bps, slippage_bps) < 0 or not 0 <= result < 1:
        raise ValueError("Transaction costs must be nonnegative and total less than 10000 bps")
    return result


def load_config():
    config = yaml.safe_load((ROOT / "config.yaml").read_text())
    dates = {key: pd.Timestamp(value) for key, value in config["dates"].items()}
    config["dates"] = dates
    tickers = config["universe"]
    if (
        len(set(tickers)) != len(tickers)
        or not {config["risk_free"], config["benchmark"]}.issubset(tickers)
        or any(not re.fullmatch(r"[A-Z]{1,5}", ticker) for ticker in tickers)
    ):
        raise ValueError("Use distinct US ETF symbols including the benchmark and risk-free proxy")
    if not dates["history_start"] < dates["backtest_start"] < dates["is_end"] < dates["end"]:
        raise ValueError("History, backtest start, IS end and backtest end must be chronological")
    execution = config["execution"]
    if min(execution["signal_lag_sessions"], execution["rebalance_every_sessions"]) < 1:
        raise ValueError("Signal lag and rebalance interval must be positive")
    model = config["model"]
    if (
        not 2 <= model["histogram_bins"] <= 256
        or not 0 < model["learning_rate"] <= 1
        or min(model["l2"], model["min_leaf_hessian"], model["min_split_gain"]) <= 0
        or min(model["ensemble_members"], model["rounds"], model["min_leaf_rows"]) < 1
        or model["min_training_rows"] < max(model["ensemble_members"], 2)
        or model["max_depth"] < 1
    ):
        raise ValueError("Invalid tree regularization or size")
    return config


def validate_bars(bars, tickers, start, end):
    required = pd.MultiIndex.from_product([FIELDS, tickers])
    bars = bars.reindex(columns=required)
    bars.index = pd.DatetimeIndex(bars.index).tz_localize(None).astype("datetime64[ns]").rename("Date")
    bars = bars.sort_index().astype(float)
    if (
        bars.empty
        or bars.index.has_duplicates
        or bars.index[0] < start
        or bars.index[-1] > end
        or bars.index[0] - start > pd.Timedelta(days=7)
        or end - bars.index[-1] > pd.Timedelta(days=7)
    ):
        raise ValueError("Yahoo Finance history is incomplete or has an invalid session index")
    if not np.isfinite(bars.to_numpy()).all():
        failed = bars.isna().any()
        raise ValueError(f"Yahoo Finance history has missing or nonfinite bars: {list(failed[failed].index)}")
    if (bars[["Open", "Close"]] <= 0).any().any() or (bars[list(FIELDS[2:])] < 0).any().any():
        raise ValueError("Price and corporate action fields are outside their expected bounds")
    return bars


def load_bars(config):
    start, end = (config["dates"][key] for key in ("history_start", "end"))
    tickers = config["universe"]
    identity = f"yahoo-split-adjusted-actions-v1|{start.date()}|{end.date()}|{','.join(sorted(tickers))}"
    snapshot_name = f"market_{sha256(identity.encode()).hexdigest()[:16]}.csv"
    snapshot = config["data"]["snapshots"][snapshot_name]
    raw = gzip.decompress(snapshot["gzip"])
    digest = sha256(raw).hexdigest()
    if digest != snapshot["sha256"]:
        raise ValueError(f"SHA-256 mismatch for snapshot {snapshot_name}")

    with BytesIO(raw) as file:
        fetched_at = file.readline().decode("utf-8").strip()
        datetime.fromisoformat(fetched_at)
        bars = pd.read_csv(file, header=[0, 1], index_col=0)
    bars = validate_bars(bars, tickers, start, end)

    input_sha256 = sha256(raw.partition(b"\n")[2]).hexdigest()
    metadata = {
        "path": "config.yaml",
        "key": "data.snapshots",
        "file": snapshot_name,
        "sha256": digest,
    }
    print(
        "Data source: Yahoo Finance (finance.yahoo.com) daily ETF bars and corporate actions via "
        "yfinance auto_adjust=False, embedded in config under data.snapshots "
        f"(decompressed sha256 {digest}); the script does not call yfinance, FRED or any host "
        "and reads no data_cache",
        flush=True,
    )
    print(f"Input SHA-256: {input_sha256}", flush=True)
    print(f"DATA_SHA256: {digest}", flush=True)
    print(f"MARKET_DATA_SNAPSHOT: {json.dumps(metadata)}", flush=True)
    return bars, fetched_at


def market_returns(bars):
    opens = bars["Open"]
    closes = bars["Close"]
    distributions = bars["Dividends"] + bars["Capital Gains"]
    # Existing shares receive the distribution before trading at the opening price.
    overnight = (opens + distributions).div(closes.shift(1))
    overnight.iloc[0] = 1.0
    intraday = closes.div(opens)
    close_total = (overnight * intraday).cumprod()
    open_total = close_total.shift(1, fill_value=1.0) * overnight
    return open_total, close_total


def make_features(close_total, config):
    prices = close_total.drop(columns=config["risk_free"])
    returns = prices.pct_change()
    settings = config["features"]
    features = {
        f"momentum_{window}": prices.pct_change(window)
        for window in settings["momentum_sessions"]
    }
    features.update({
        f"volatility_{window}": returns.rolling(window).std()
        for window in settings["volatility_sessions"]
    })
    window = settings["moving_average_sessions"]
    features[f"relative_to_average_{window}"] = prices / prices.rolling(window).mean() - 1
    return pd.concat(features, axis=1)


def log_growth_derivatives(scores, returns):
    weights = softmax(scores)
    asset_growth = 1 + returns
    growth = np.sum(weights * asset_growth, axis=-1, keepdims=True)
    gradient = weights * (1 - asset_growth / growth)
    diagonal = gradient * (1 - 2 * weights) + gradient**2
    return gradient, diagonal


def softmax(scores):
    relative = np.exp(scores - scores.max(axis=-1, keepdims=True))
    return relative / relative.sum(axis=-1, keepdims=True)


@njit
def best_split(bins, rows, gradient, hessian, total_g, total_h,
               bin_count, min_rows, min_mass, l2, min_gain):
    """Find a shared split by summing the Newton gains across assets."""
    feature_count = bins.shape[1]
    asset_count = gradient.shape[1]
    parent_score = np.sum(total_g**2 / (total_h + l2))
    best_feature, best_cut = -1, -1
    best_gain = min_gain

    for feature in range(feature_count):
        counts = np.zeros(bin_count, dtype=np.int64)
        g_bins = np.zeros((bin_count, asset_count))
        h_bins = np.zeros((bin_count, asset_count))
        for row in rows:
            group = bins[row, feature]
            counts[group] += 1
            for asset in range(asset_count):
                g_bins[group, asset] += gradient[row, asset]
                h_bins[group, asset] += hessian[row, asset]

        left_rows = 0
        left_g = np.zeros(asset_count)
        left_h = np.zeros(asset_count)
        for cut in range(bin_count - 1):
            if counts[cut] == 0:
                continue
            left_rows += counts[cut]
            left_g += g_bins[cut]
            left_h += h_bins[cut]
            if left_rows < min_rows or len(rows) - left_rows < min_rows:
                continue
            right_h = total_h - left_h
            if left_h.sum() < min_mass or right_h.sum() < min_mass:
                continue
            right_g = total_g - left_g
            gain = 0.5 * (
                np.sum(left_g**2 / (left_h + l2) + right_g**2 / (right_h + l2)) - parent_score
            )
            if gain > best_gain:
                best_feature, best_cut, best_gain = feature, cut, gain
    return best_feature, best_cut


def grow_tree(bins, query_bins, gradient, hessian, settings):
    """Apply one tree's vector leaves to every training row and the current query."""
    row_steps = np.empty_like(gradient)
    query_step = np.empty(gradient.shape[1])
    l2 = settings["l2"]

    def visit(rows, depth, query_here):
        total_g = gradient[rows].sum(axis=0)
        total_h = hessian[rows].sum(axis=0)
        feature = -1
        if depth < settings["max_depth"] and len(rows) >= 2 * settings["min_leaf_rows"]:
            feature, cut = best_split(
                bins, rows, gradient, hessian, total_g, total_h,
                settings["histogram_bins"], settings["min_leaf_rows"],
                settings["min_leaf_hessian"], l2, settings["min_split_gain"],
            )
        if feature == -1:
            step = -total_g / (total_h + l2)
            row_steps[rows] = step
            if query_here:
                query_step[:] = step
            return
        left = bins[rows, feature] <= cut
        query_left = query_bins[feature] <= cut
        visit(rows[left], depth + 1, query_here and query_left)
        visit(rows[~left], depth + 1, query_here and not query_left)

    visit(np.arange(len(bins)), 0, True)
    return row_steps, query_step


def fit_weights(features, returns, query, settings):
    """Fit vector trees with cut points estimated only from the supplied training rows."""
    probabilities = np.arange(1, settings["histogram_bins"]) / settings["histogram_bins"]
    cuts = np.quantile(features, probabilities, axis=0)
    bins = np.column_stack([
        np.searchsorted(cuts[:, feature], features[:, feature], side="left")
        for feature in range(features.shape[1])
    ]).astype(np.uint8)
    query_bins = np.sum(query[None, :] > cuts, axis=0)
    scores = np.zeros_like(returns)
    query_scores = np.zeros(returns.shape[1])
    for _ in range(settings["rounds"]):
        gradient, diagonal = log_growth_derivatives(scores, returns)
        row_steps, query_step = grow_tree(bins, query_bins, gradient, np.abs(diagonal), settings)
        scores += settings["learning_rate"] * row_steps
        query_scores += settings["learning_rate"] * query_step
    return softmax(query_scores)


def target_weights(features, open_total, fill_rows, config, settings):
    execution = config["execution"]
    lag = execution["signal_lag_sessions"]
    horizon = execution["rebalance_every_sessions"]
    maturity_offset = lag + horizon
    x = features.to_numpy()
    labels = (open_total.shift(-maturity_offset) / open_total.shift(-lag) - 1).to_numpy()
    good_features = np.isfinite(x).all(axis=1)
    targets = {}
    for fill_row in fill_rows:
        signal_row = fill_row - lag
        if signal_row < 0 or not good_features[signal_row]:
            raise ValueError(f"Missing features before the {features.index[fill_row].date()} fill")
        # A training row can enter only after the label's exit open has occurred.
        last_eligible = signal_row - maturity_offset
        train = np.flatnonzero(good_features[:max(0, last_eligible + 1)])
        if len(train) < settings["min_training_rows"]:
            raise ValueError(f"Not enough matured training labels on {features.index[signal_row].date()}")
        returns = labels[train]
        if train[-1] + maturity_offset > signal_row or not np.isfinite(returns).all():
            raise RuntimeError("Training includes an unfinished or missing label")
        dropped_rows = np.random.default_rng(0).choice(
            len(train), size=settings["ensemble_members"], replace=False
        )
        members = []
        for dropped in dropped_rows:
            kept = np.arange(len(train)) != dropped
            members.append(fit_weights(x[train[kept]], returns[kept], x[signal_row], settings))
        targets[fill_row] = np.mean(members, axis=0)
    return targets


def rebalance(opening_values, cash, target, charge):
    if not np.isfinite(target).all() or (target < 0).any() or not np.isclose(target.sum(), 1):
        raise ValueError("Target weights must be nonnegative and sum to one")
    before = cash + opening_values.sum()
    # A fully invested target must reserve both buy and sell costs.
    # The budget is monotonic in the proposed invested amount for charge < 1.
    low, high = 0.0, before
    for _ in range(52):
        middle = (low + high) / 2
        proposed = middle * target
        used = proposed.sum() + charge * np.abs(proposed - opening_values).sum()
        if used <= before:
            low = middle
        else:
            high = middle
    new_values = low * target
    traded_values = np.abs(new_values - opening_values)
    remaining = before - (new_values.sum() + charge * traded_values.sum())
    if remaining < 0:
        raise RuntimeError("Rebalance used more than available cash and sale proceeds")
    return new_values, remaining, traded_values.sum() / before, int(
        np.count_nonzero(traded_values > before * 1e-12)
    )


def simulate(bars, first_row, targets, charge):
    opens = bars["Open"].to_numpy()
    closes = bars["Close"].to_numpy()
    distributions = (bars["Dividends"] + bars["Capital Gains"]).to_numpy()
    positions = np.zeros(opens.shape[1])
    cash, previous_value = 1.0, 1.0
    records = []
    for row in range(first_row, len(bars)):
        opening = opens[row]
        positions *= 1 + distributions[row] / opening
        turnover, trades = 0.0, 0
        if row in targets:
            invested, cash, turnover, trades = rebalance(
                positions * opening, cash, targets[row], charge
            )
            positions = invested / opening
        ending_value = cash + positions @ closes[row]
        records.append((ending_value / previous_value - 1, turnover, trades))
        previous_value = ending_value
    return pd.DataFrame(records, index=bars.index[first_row:], columns=["return", "turnover", "n_trades"])


def score(daily_results, risk_free):
    returns = daily_results["return"]
    excess = returns - risk_free.loc[returns.index]
    years = len(returns) / ANNUAL_SESSIONS
    if len(returns) < 2:
        raise ValueError("A reporting period must contain at least two sessions")
    growth = np.r_[1.0, (1 + returns).cumprod().to_numpy()]
    volatility = returns.std() * np.sqrt(ANNUAL_SESSIONS)
    excess_volatility = excess.std() * np.sqrt(ANNUAL_SESSIONS)
    return {
        "cagr": float(growth[-1] ** (1 / years) - 1),
        "ann_vol": float(volatility),
        "sharpe": float(returns.mean() * ANNUAL_SESSIONS / volatility) if volatility else 0.0,
        "sharpe_excess": float(excess.mean() * ANNUAL_SESSIONS / excess_volatility) if excess_volatility else 0.0,
        "max_drawdown": float((growth / np.maximum.accumulate(growth) - 1).min()),
        "total_return": float(growth[-1] - 1),
        "turnover": float(daily_results["turnover"].sum() / years),
        "n_trades": int(daily_results["n_trades"].sum()),
    }


def report_periods(daily_results, risk_free, is_end):
    return {
        "is": score(daily_results.loc[:is_end], risk_free),
        "oos": score(daily_results.loc[daily_results.index > is_end], risk_free),
        "full": score(daily_results, risk_free),
    }


def print_metrics(label, metrics):
    print(f"{label}: {json.dumps(metrics, allow_nan=False)}", flush=True)


def main():
    config = load_config()
    bars, fetched_at = load_bars(config)
    print(f"DATA_FETCHED_AT: {fetched_at}", flush=True)
    print(f"PRICE_ADJUSTMENT: {PRICE_ADJUSTMENT}", flush=True)
    execution = config["execution"]
    charge = rate(execution["cost_bps"], execution["slippage_bps"])
    model = config["model"]
    robustness = config["robustness"]
    alternative_l2 = robustness["l2_values"]
    if len(set(alternative_l2)) != len(alternative_l2) or any(
        value <= 0 or value == model["l2"] for value in alternative_l2
    ):
        raise ValueError("Robustness L2 parameters must be positive and distinct from the default")
    stress_charge = rate(robustness["high_cost_bps"], robustness["high_slippage_bps"])
    if stress_charge <= charge:
        raise ValueError("The higher-cost scenario must raise the combined cost and slippage")

    first = bars.index.searchsorted(config["dates"]["backtest_start"])
    is_end = config["dates"]["is_end"]
    split = bars.index.searchsorted(is_end, side="right")
    every = execution["rebalance_every_sessions"]
    fill_rows = np.arange(first, len(bars), every)
    is_rows = fill_rows[fill_rows < split]
    oos_rows = fill_rows[fill_rows >= split]
    if not len(is_rows) or not len(oos_rows):
        raise ValueError("Both reporting periods must contain a scheduled fill")
    is_bars = bars.iloc[:split]
    is_opens, is_closes = market_returns(is_bars)
    is_features = make_features(is_closes, config)
    ref = config["risk_free"]
    is_rf = is_closes[ref].pct_change()
    is_rf.iloc[first] = is_closes[ref].iloc[first] / is_opens[ref].iloc[first] - 1

    is_targets = target_weights(is_features, is_opens, is_rows, config, model)
    is_daily = simulate(is_bars, first, is_targets, charge)
    combos = 1
    print("ROBUSTNESS: IS only, fixed defaults", flush=True)
    print_metrics(f"IS default l2={model['l2']}", score(is_daily, is_rf))
    for l2 in alternative_l2:
        targets = target_weights(is_features, is_opens, is_rows, config, {**model, "l2": l2})
        print_metrics(f"IS sensitivity l2={l2}", score(simulate(is_bars, first, targets, charge), is_rf))
        combos += 1
    stress_daily = simulate(is_bars, first, is_targets, stress_charge)
    print_metrics(
        f"IS stress cost_bps={robustness['high_cost_bps']} slippage_bps={robustness['high_slippage_bps']}",
        score(stress_daily, is_rf),
    )
    combos += 1
    print(f"PARAM_COMBOS_TRIED: {combos}", flush=True)

    open_total, close_total = market_returns(bars)
    features = make_features(close_total, config)
    pd.testing.assert_frame_equal(features.iloc[:split], is_features, check_exact=True)
    pd.testing.assert_frame_equal(open_total.iloc[:split], is_opens, check_exact=True)
    oos_targets = target_weights(features, open_total, oos_rows, config, model)
    official = simulate(bars, first, {**is_targets, **oos_targets}, charge)
    pd.testing.assert_frame_equal(official.loc[:is_end], is_daily, check_exact=True)
    ref_returns = close_total[ref].pct_change()
    ref_returns.iloc[first] = close_total[ref].iloc[first] / open_total[ref].iloc[first] - 1
    strategy_scores = report_periods(official, ref_returns, is_end)
    if any(strategy_scores[period]["n_trades"] == 0 for period in ("is", "oos")):
        raise RuntimeError("No strategy trades in one of the reporting periods")

    benchmark = config["benchmark"]
    benchmark_target = (np.array(config["universe"]) == benchmark).astype(float)
    benchmark_daily = simulate(bars, first, {first: benchmark_target}, charge)
    benchmark_scores = report_periods(benchmark_daily, ref_returns, is_end)
    print(
        "LOOK_AHEAD_CHECK: close-derived signals, later open fills and sizing, "
        "matured open-to-open labels, market bars and dated distributions only, "
        "split-adjusted units, fixed settings, exact IS prefix match",
        flush=True,
    )
    print("STATUS: 已回测，待复核", flush=True)
    for period in ("is", "oos", "full"):
        print_metrics(f"STRATEGY {period.upper()}", strategy_scores[period])
        print_metrics(f"BENCHMARK {benchmark} {period.upper()}", benchmark_scores[period])
    print_metrics("RESULTS_JSON", {
        "strategy": config["strategy"],
        "data_range": {
            "start": official.index[0].date().isoformat(),
            "end": official.index[-1].date().isoformat(),
        },
        **strategy_scores,
        "benchmark": {"ticker": benchmark, **benchmark_scores},
    })


if __name__ == "__main__":
    signal.alarm(840)
    try:
        main()
    finally:
        signal.alarm(0)
